+struct Tolerances {
+    Curve cosine, risk;
+    Tolerances(const char* path, int bits, int tables, double approximation) {
+        const double maximum = std::min(1.0, approximation + 0.055);
+        for (int a = 0; a < levels; ++a) {
+            cosine.p[a] = maximum*(1.0 - (a+1.0)/levels);
+            risk.p[a] = 0.003;
+        }
+        std::ifstream input(path, std::ios::binary);
+        char magic[8];
+        int32_t shape[3];
+        double step[2];
+        if (!input.read(magic, sizeof(magic)) || std::memcmp(magic, "FARGOSQ1", 8) ||
+            !input.read(reinterpret_cast<char*>(shape), sizeof(shape)) ||
+            !input.read(reinterpret_cast<char*>(step), sizeof(step)) ||
+            shape[0] != bits || shape[1] <= 0 || shape[2] <= 0 ||
+            !(step[0] > 0) || !(step[1] > 0)) return;
+
+        std::vector<double> cdf(static_cast<size_t>(shape[1])*shape[2]);
+        if (!input.read(reinterpret_cast<char*>(cdf.data()), cdf.size()*sizeof(double))) return;
+        auto row = [&](double r) {
+            const int i = std::min(shape[1]-1, static_cast<int>(std::ceil(std::acos(r)/step[0])));
+            return cdf.data()+i*shape[2];
+        };
+        const double target = std::pow(0.9, 1.0/tables);
+        for (int a = 0; a < levels; ++a) {
+            const double r = cosine.p[a];
+            const double* proxy = row(std::min(1.0, r/(approximation+0.025)));
+            const int j = std::min(shape[2]-1, static_cast<int>(
+                std::upper_bound(proxy, proxy+shape[2], target)-proxy));
